// Parse n8n Google Gemini node response - returns JSON directly
const response = $input.item.json;

// The native node returns the JSON directly in the output
// Check if it's already the parsed object we want
if (response.title && response.scenes && Array.isArray(response.scenes)) {
  return [{ json: response }];
}

// Fallback: extract from text fields
let text = '';
if (typeof response === 'string') {
  text = response;
} else if (response.text) {
  text = typeof response.text === 'string' ? response.text : JSON.stringify(response.text);
} else if (response.content) {
  text = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
} else {
  text = JSON.stringify(response);
}

// Clean and parse
text = String(text).replace(/```json|```/g, '').trim();

try {
  const parsed = JSON.parse(text);
  return [{ json: parsed }];
} catch (e) {
  return [{ json: { 
    error: 'Failed to parse', 
    rawText: text,
    keys: Object.keys(response)
  } }];
}

// Build Pollinations URL with all parameters evaluated
const CHARACTER_PROMPT = 'Benny the bunny, round soft blue shirt, big ears, 2D vector illustration, nursery rhyme style, bright pastel colors, simple shapes, clean lines';

// Split In Batches outputs each scene directly in $json
const fullPrompt = CHARACTER_PROMPT + ', ' + $json.prompt;
const encoded = encodeURIComponent(fullPrompt);
const seed = 12345 + $json.id;

const url = `https://image.pollinations.ai/prompt/${encoded}?width=1920&height=1080&seed=${seed}&model=flux&nologo=true`;

return [{
  json: {
    ...$json,
    pollinationsUrl: url
  }
}];

// Combine all scenes back into single script with images
const items = $input.all();
const first = items[0].json;
const script = { ...first };
script.sceneImages = items.map(item => item.json.pollinationsResult);
return [{ json: script }];

// Generate voiceover using Edge TTS (Microsoft, free, no key)
// Returns audio buffer + timing for lyric sync

const script = $input.item.json;
const scenes = script.scenes;

let fullText = '';
const timing = [];
let currentTime = 0;

for (const scene of scenes) {
  if (scene.narration) {
    timing.push({ type: 'narration', sceneId: scene.id, start: currentTime, text: scene.narration });
    fullText += scene.narration + ' ';
    currentTime += scene.narration.length * 0.08;
  }
  if (scene.lyrics) {
    timing.push({ type: 'lyrics', sceneId: scene.id, start: currentTime, text: scene.lyrics, duration: scene.duration });
    fullText += scene.lyrics + ' ';
    currentTime += scene.duration;
  }
}

const voice = 'en-US-JennyNeural';
const ssml = `<speak version='1.0' xml:lang='en-US'><voice name='${voice}'>${fullText}</voice></speak>`;

const response = await fetch('https://edge.microsoft.com/translate/tts', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ text: ssml, voice })
});

const audioBuffer = await response.arrayBuffer();
const audioBase64 = Buffer.from(audioBuffer).toString('base64');

return [{ json: { ...script, audioBase64, timing } }];
